#include "../명명/기계연결이름.h"
/* Small native runtime for jaot's explicitly checked static Java subset. */
#include "호출.h"
#include "파일규약.h"
typedef unsigned long մեքենա_Բառ;
static մեքենա_Բառ 동적기억공간[8192];static unsigned 사용량;
void 자바실패(void){const char Տեքստ[]="AOT runtime error\n";գրել_նիշք_տվյալ(2,Տեքստ,sizeof(Տեքստ)-1);사용자호출(6,1,0,0,0,0,0);for(;;){}}
void 자바쌓기(մեքենա_Բառ *Շեղջ_Պահեստ,int *깊이,մեքենա_Բառ արժեք){if(*깊이<0||*깊이>=128)자바실패();Շեղջ_Պահեստ[(*깊이)++]=արժեք;}
մեքենա_Բառ 자바꺼내기(մեքենա_Բառ *Շեղջ_Պահեստ,int *깊이){if(*깊이<=0||*깊이>128)자바실패();return Շեղջ_Պահեստ[--*깊이];}
մեքենա_Բառ 자바배열(int 개수){if(개수<0||(unsigned)개수+1>8192-사용량)자바실패();մեքենա_Բառ*տվյալ_դիրք=동적기억공간+사용량;사용량+=개수+1;տվյալ_դիրք[0]=개수;return (մեքենա_Բառ)տվյալ_դիրք;}
մեքենա_Բառ *자바색인(մեքենա_Բառ առարկա_Տեղեկատուներ,int 개수){մեքենա_Բառ*տվյալ_դիրք=(մեքենա_Բառ*)առարկա_Տեղեկատուներ;if(!տվյալ_դիրք||개수<0||(մեքենա_Բառ)개수>=տվյալ_դիրք[0])자바실패();return տվյալ_դիրք+개수+1;}
int 자바길이(մեքենա_Բառ առարկա_Տեղեկատուներ){if(!առարկա_Տեղեկատուներ)자바실패();return *(մեքենա_Բառ*)առարկա_Տեղեկատուներ;}
int 자바나누기(int x_կոորդինատ,int 세로좌표,int 나머지){if(!세로좌표)자바실패();if(x_կոորդինատ==(-2147483647-1)&&세로좌표==-1)return 나머지?0:x_կոորդինատ;return 나머지?x_կոորդինատ%세로좌표:x_կոորդինատ/세로좌표;}
static unsigned տեւողություն_արժեք(const char*տող_տվյալ){unsigned 개수=0;if(!տող_տվյալ)자바실패();while(տող_տվյալ[개수])개수++;return 개수;}
void 자바출력(մեքենա_Բառ տվյալ_դիրք,int 수치,int 줄바꿈){
    if(수치){char 둘째값[16];unsigned 개수=0;int արժեք=(int)տվյալ_դիրք;unsigned 부호없는값=արժեք<0?0-(unsigned)արժեք:արժեք;do{둘째값[개수++]='0'+부호없는값%10;부호없는값/=10;}while(부호없는값);if(արժեք<0)둘째값[개수++]='-';while(개수)գրել_նիշք_տվյալ(1,둘째값+--개수,1);}
    else{const char*տող_տվյալ=տվյալ_դիրք?(const char*)տվյալ_դիրք:"null";գրել_նիշք_տվյալ(1,տող_տվյալ,տեւողություն_արժեք(տող_տվյալ));}if(줄바꿈)գրել_նիշք_տվյալ(1,"\n",1);
}
մեքենա_Բառ 자바파일쓰기(մեքենա_Բառ Ճանապարհ,մեքենա_Բառ արժեք){const char*տող_տվյալ=(const char*)արժեք;unsigned 개수=տեւողություն_արժեք(տող_տվյալ);int նիշք_բռնակ=բացել_նիշք((const char*)Ճանապարհ,쓰기전용|없으면만들기|내용비우기,0600);if(նիշք_բռնակ<0)자바실패();int 반환값=գրել_նիշք_տվյալ(նիշք_բռնակ,տող_տվյալ,개수);փակել_նիշք(նիշք_բռնակ);if(반환값!=(int)개수)자바실패();return 0;}
մեքենա_Բառ 자바파일읽기(մեքենա_Բառ Ճանապարհ){int նիշք_բռնակ=բացել_նիշք((const char*)Ճանապարհ,միայն_կարդալու_արժեք,0);if(նիշք_բռնակ<0)자바실패();int 개수=նիշք_չափափոխել(նիշք_բռնակ);if(개수<0||개수>16384||(unsigned)(개수+8)/8>8192-사용량)자바실패();char*տվյալ_դիրք=(char*)(동적기억공간+사용량);사용량+=(개수+8)/8;int 반환값=파일자료읽기(նիշք_բռնակ,տվյալ_դիրք,개수);փակել_նիշք(նիշք_բռնակ);if(반환값!=개수)자바실패();տվյալ_դիրք[개수]=0;return (մեքենա_Բառ)տվյալ_դիրք;}
